+import { resolve } from "@std/path";
+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions } from "./types.ts";
+
+export interface LoadedConfig {
+  path?: string;
+  values: Record<string, unknown>;
+}
+
+export async function loadConfig(options: ConfigOptions): Promise<LoadedConfig> {
+  const paths = options.searchPaths?.length ? options.searchPaths : ["."];
+  const formats = options.formats?.length ? options.formats : [".json", ".rc"];
+  const matches: Array<{ path: string; values: Record<string, unknown> }> = [];
+
+  for (const searchPath of paths) {
+    for (const format of formats) {
+      const path = resolve(searchPath, `${options.name}${format}`);
+      const content = await readFileIfExists(path);
+      if (content === undefined) continue;
+      matches.push({ path, values: parseConfig(path, content, format, options.parser) });
+      break;
+    }
+    if (matches.length && !options.mergeConfigs) break;
+  }
+
+  if (!matches.length) return { values: {} };
+  // Earlier search paths take precedence.
+  const values = matches.reduceRight<Record<string, unknown>>(
+    (result, match) => ({ ...result, ...match.values }),
+    {},
+  );
+  return { path: matches[0].path, values };
+}
+
+function parseConfig(
+  path: string,
+  content: string,
+  format: string,
+  parser?: ConfigOptions["parser"],
+): Record<string, unknown> {
+  try {
+    const values = parser ? parser(content) : format === ".rc"
+      ? parseRc(content)
+      : JSON.parse(content);
+    if (!isPlainObject(values)) throw new Error("Config must be a plain object.");
+    return flattenAndCamelCase(values);
+  } catch (error) {
+    throw new ConfigParseError(path, error);
+  }
+}
+
+function parseRc(content: string): Record<string, unknown> {
+  const values: Record<string, unknown> = {};
+  for (const line of content.split(/\\r?\
/)) {
+    const trimmed = line.trim();
+    if (!trimmed || trimmed.startsWith("#")) continue;
+    const index = trimmed.indexOf("=");
+    if (index < 0) throw new Error("Expected key=value.");
+    const key = trimmed.slice(0, index).trim();
+    let value = trimmed.slice(index + 1).trim();
+    if (!key) throw new Error("Missing key.");
+    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
+      value = value.slice(1, -1);
+    }
+    values[key] = coerceRcValue(value);
+  }
+  return values;
+}
+
+function coerceRcValue(value: string): string | number | boolean {
+  if (value === "true") return true;
+  if (value === "false") return false;
+  if (/^-?(?:\\d+\\.?\\d*|\\.\\d+)$/.test(value)) return Number(value);
+  return value;
+}
+
+function flattenAndCamelCase(values: Record<string, unknown>): Record<string, unknown> {
+  const result: Record<string, unknown> = {};
+  const visit = (value: unknown, key: string) => {
+    if (isPlainObject(value)) {
+      for (const [childKey, childValue] of Object.entries(value)) {
+        visit(childValue, key ? `${key}.${childKey}` : childKey);
+      }
+    } else {
+      result[toCamelCase(key)] = value;
+    }
+  };
+  for (const [key, value] of Object.entries(values)) visit(value, key);
+  return result;
+}
+
+function toCamelCase(value: string): string {
+  return value.replace(/-([a-zA-Z0-9])/g, (_, char) => char.toUpperCase());
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return !!value && typeof value === "object" && !Array.isArray(value) &&
+    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
+}
+
+async function readFileIfExists(path: string): Promise<string | undefined> {
+  // dnt-shim-ignore
+  const { Deno } = globalThis as { Deno?: { readTextFile(path: string): Promise<string> } };
+  try {
+    if (Deno) return await Deno.readTextFile(path);
+    const fs = await import("node:fs/promises");
+    return await fs.readFile(path, "utf8");
+  } catch (error) {
+    if ((error as { code?: string; name?: string }).code === "ENOENT" ||
+      (error as { name?: string }).name === "NotFound") return undefined;
+    throw error;
+  }
+}
